<?php require __DIR__.'/auth.php'; if(!empty($_SESSION['user'])){header('Location: index.php');exit;} $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){try{check_csrf();$st=db()->prepare('SELECT id,username,password_hash,role,enabled FROM users WHERE username=? LIMIT 1');$st->execute([trim($_POST['username']??'')]);$u=$st->fetch();if($u&&$u['enabled']&&password_verify($_POST['password']??'',$u['password_hash'])){session_regenerate_id(true);$_SESSION['user']=['id'=>$u['id'],'username'=>$u['username'],'role'=>$u['role']];header('Location: index.php');exit;} $error='Invalid username or password';}catch(Throwable $e){$error='Database unavailable';}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Monitoring Login</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container" style="max-width:420px;padding-top:12vh"><div class="card shadow-sm"><div class="card-body p-4"><h3 class="mb-1">Infrastructure Monitoring</h3><p class="text-muted">Sign in to continue</p><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div class="mb-3"><label class="form-label">Username</label><input class="form-control" name="username" required autofocus></div><div class="mb-3"><label class="form-label">Password</label><input class="form-control" type="password" name="password" required></div><button class="btn btn-dark w-100">Sign in</button></form></div></div></main></body></html>
